@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V21PriceHistoryIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");r.add("management.health.redis.enabled",()->false);r.add("management.health.rabbit.enabled",()->false);r.add("pawday.outbox.workers-enabled",()->false);r.add("pawday.outbox.consumer-enabled",()->false);r.add("pawday.search.enabled",()->false);r.add("pawday.storage.cleanup-enabled",()->false);}
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 String admin,merchant,foreign,reader,colleague;UUID adminPrincipal,adminSession,merchantId,store,otherStore,principal;String sku;
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}

 String key(){return UUID.randomUUID().toString();}
 String identity(String realm,UUID m,List<String> permissions){UUID p=UUID.randomUUID(),role=UUID.randomUUID();if(realm.equals("CONSUMER")){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,?,?,?,?)",p,realm,m,key(),"TEST-ONLY");
  db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,?,?,'Offer test')",role,realm,key());for(String permission:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,permission);db.update("INSERT INTO principal_role VALUES (?,?,?)",p,role,realm);UUID session=UUID.randomUUID();String t=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'OFFER-IT',?,?,?)",session,p,crypto.hash(t),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));if(realm.equals("ADMIN")&&permissions.contains("offer.admin.manage")){adminSession=session;adminPrincipal=p;}if(realm.equals("MERCHANT")){principal=p;db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,m,store);}return t;
 }
 @BeforeEach void setup(){merchantId=UUID.randomUUID();store=UUID.randomUUID();otherStore=UUID.randomUUID();db.update("INSERT INTO merchant(id,name,status) VALUES (?,?,'ACTIVE')",merchantId,key());db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST scope'),(?,?,'TEST hidden')",store,merchantId,otherStore,merchantId);
  admin=identity("ADMIN",null,List.of("offer.admin.read","offer.admin.manage"));reader=identity("ADMIN",null,List.of("offer.admin.read"));merchant=identity("MERCHANT",merchantId,List.of("offer.read","offer.write","inventory.adjust","offer.default-scope"));colleague=identity("MERCHANT",merchantId,List.of("offer.read","offer.write","inventory.adjust"));UUID m=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST foreign','ACTIVE')",m);UUID saved=store;store=UUID.randomUUID();db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST foreign store')",store,m);foreign=identity("MERCHANT",m,List.of("offer.read","offer.write","inventory.adjust"));store=saved;
  UUID brand=UUID.randomUUID(),spu=UUID.randomUUID(),k=UUID.randomUUID();sku=k.toString();db.update("INSERT INTO brands(id,name,source_ref) VALUES (?,?,'TEST-ONLY')",brand,key());db.update("INSERT INTO spus(id,brand_id,name,pet_category,category) VALUES (?,?,'TEST-ONLY','CAT','DRY_FOOD')",spu,brand);db.update("INSERT INTO skus(id,spu_id,sku_code,weight_g,package_unit) VALUES (?,?,?,1000,'BAG')",k,spu,key());db.update("INSERT INTO sku_standard_versions(id,sku_id,version_no,status,ingredients,nutrients,allergens_known,life_stage_ids,source_refs,source_updated_on,created_by,published_at) VALUES (?,?,1,'PUBLISHED','[\"TEST-ONLY\"]','[]',false,'[]','[\"TEST-ONLY source\"]','2026-10-01',?,clock_timestamp())",UUID.randomUUID(),k,adminPrincipal);
 }
 Response req(String method,String path,Object payload,String token,Map<String,String> headers){try{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(20));if(token!=null)b.header("Authorization","Bearer "+token);headers.forEach(b::header);if(payload==null)b.method(method,HttpRequest.BodyPublishers.noBody());else b.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(payload)));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofString());var body=json.readTree(response.body());SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",body));return new Response(response.statusCode(),body);}catch(Exception e){throw new AssertionError(e);}}
 Response read(String path,String token){return req("GET",path,null,token,Map.of());}
 Map<String,Object> createBody(UUID scope){var b=new LinkedHashMap<String,Object>(Map.of("sku_id",sku,"sale_price_fen",1000,"member_price_fen",900,"fulfillment_sla","TEST-ONLY 48h"));b.put("store_id",scope==null?null:scope.toString());return b;}
 String create(){var r=req("POST","/merchant/offers",createBody(store),merchant,Map.of("Idempotency-Key",key()));assertEquals(201,r.status(),r.body().toString());return r.id();}
 Response patch(String offer,Map<String,Object>b,int version){return req("PATCH","/merchant/offers/"+offer,b,merchant,Map.of("Idempotency-Key",key(),"If-Match","\""+version+"\""));}
 Response adjust(String offer,int delta,int version,String k,String who){return req("POST","/merchant/offers/"+offer+"/inventory-adjustments",Map.of("delta_qty",delta,"reason_code","COUNT_CORRECTION","expected_version",version),who,Map.of("Idempotency-Key",k));}
 String proof(){String p=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,'offer.admin.manage',?,?)",crypto.hash(p),adminSession,Timestamp.from(clock.instant().plusSeconds(120)),Timestamp.from(clock.instant()));return p;}
 Response state(String offer,String action,int version,String who,String p,String k){var h=new HashMap<String,String>(Map.of("Idempotency-Key",k,"If-Match","\""+version+"\""));if(p!=null)h.put("X-Reverify-Token",p);return req("POST","/"+(who.equals(admin)||who.equals(reader)?"admin":"merchant")+"/offers/"+offer+"/"+action,Map.of("reason","TEST-ONLY lifecycle"),who,h);}
 long balance(String offer){return db.queryForObject("SELECT on_hand_qty FROM inventory_balances WHERE offer_id=?",Long.class,UUID.fromString(offer));}
 @AfterAll static void close()throws Exception{Files.writeString(Path.of("target/v21-contract-samples.json"),JsonMapper.builder().build().writeValueAsString(SAMPLES));PG.close();}

 long snapshots(String offer){return db.queryForObject("SELECT count(*) FROM offer_price_snapshots WHERE offer_id=?",Long.class,UUID.fromString(offer));}
 String active(){String id=create();assertEquals(200,state(id,"activate",0,merchant,null,key()).status());return id;}
 Response history(String realm,String id,int days,String who){return read("/"+realm+"/offers/"+id+"/price-history?days="+days,who);}
 @Test void pastDaysAreUnknownAndPublishedDailyPointsHaveExactBoundaries(){String id=active();var r=history("public",id,30,null);assertEquals(200,r.status(),r.body().toString());var h=r.data();assertEquals(30,h.get("points").size());assertEquals(1,h.get("observed_days").asInt());for(int n=0;n<29;n++)assertTrue(h.get("points").get(n).get("sale_price_fen").isNull());assertEquals(1000,h.get("points").get(29).get("sale_price_fen").asInt());assertEquals(900,h.get("points").get(29).get("member_price_fen").asInt());LocalDate end=Instant.parse(h.get("as_of").asString()).atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();assertEquals(end.toString(),h.get("to_date").asString());assertEquals(end.minusDays(29).toString(),h.get("from_date").asString());assertEquals(90,history("public",id,90,null).data().get("points").size());}
 @Test void idempotentPatchRecordsOnceAndUnchangedQuoteDoesNotRecord(){String id=active();assertEquals(2,snapshots(id));assertEquals(200,patch(id,Map.of("fulfillment_sla","TEST-ONLY changed"),1).status());assertEquals(2,snapshots(id));String k=key();var body=Map.of("sale_price_fen",1200);var headers=Map.of("Idempotency-Key",k,"If-Match","\"2\"");assertEquals(200,req("PATCH","/merchant/offers/"+id,body,merchant,headers).status());assertEquals(200,req("PATCH","/merchant/offers/"+id,body,merchant,headers).status());assertEquals(3,snapshots(id));assertEquals(1200,history("merchant",id,30,merchant).data().get("current_sale_price_fen").asInt());}
 @Test void auditFailureRollsBackQuotationHistoryAndOutbox(){String id=active();long before=snapshots(id),outbox=db.queryForObject("SELECT count(*) FROM outbox_event",Long.class);db.execute("CREATE FUNCTION v21_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='offer.patch' THEN RAISE EXCEPTION 'TEST_ONLY_HISTORY_ROLLBACK'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER v21_fail_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION v21_fail_audit()");try{assertEquals(503,patch(id,Map.of("sale_price_fen",1400),1).status());assertEquals(before,snapshots(id));assertEquals(outbox,db.queryForObject("SELECT count(*) FROM outbox_event",Long.class));assertEquals(1000,history("public",id,30,null).data().get("current_sale_price_fen").asInt());}finally{db.execute("DROP TRIGGER v21_fail_audit ON audit_event");db.execute("DROP FUNCTION v21_fail_audit()");}}
 @Test void rollbackAndImmutableStoragePreventSilentHistoryRewrite(){String id=active();long count=snapshots(id);try(var c=db.getDataSource().getConnection()){c.setAutoCommit(false);try(var statement=c.prepareStatement("UPDATE offers SET sale_price_fen=1700 WHERE id=?")){statement.setObject(1,UUID.fromString(id));statement.executeUpdate();}c.rollback();}catch(Exception e){throw new AssertionError(e);}assertEquals(count,snapshots(id));assertThrows(RuntimeException.class,()->db.update("UPDATE offer_price_snapshots SET sale_price_fen=42 WHERE offer_id=?",UUID.fromString(id)));assertThrows(RuntimeException.class,()->db.update("DELETE FROM offer_price_snapshots WHERE offer_id=?",UUID.fromString(id)));assertThrows(RuntimeException.class,()->db.execute("TRUNCATE offer_price_snapshots"));assertEquals(count,snapshots(id));}
 void fixturePoint(String id,int ago,int price,String status){Instant at=LocalDate.now(ZoneId.of("Asia/Shanghai")).minusDays(ago).atTime(23,59).atZone(ZoneId.of("Asia/Shanghai")).toInstant();db.update("INSERT INTO offer_price_snapshots(offer_id,merchant_id,store_id,sku_id,offer_version,sale_price_fen,member_price_fen,sale_status,publicly_recorded,kind,recorded_at) SELECT id,merchant_id,store_id,sku_id,version,?,NULL,?,?,'PRICE_CHANGE',? FROM offers WHERE id=?",price,status,status.equals("ACTIVE"),Timestamp.from(at),UUID.fromString(id));}
 @Test void pausedHistoricalPricesAreMaskedAndGapsPreserved(){String id=active();fixturePoint(id,2,850,"ACTIVE");fixturePoint(id,1,1300,"PAUSED");var publicHistory=history("public",id,30,null).data();assertEquals(850,publicHistory.get("points").get(27).get("sale_price_fen").asInt());assertTrue(publicHistory.get("points").get(28).get("sale_price_fen").isNull());assertTrue(publicHistory.get("points").get(28).get("sale_status").isNull());assertTrue(publicHistory.get("points").get(28).get("recorded_at").isNull());assertEquals(1300,history("merchant",id,30,merchant).data().get("points").get(28).get("sale_price_fen").asInt());assertEquals(200,state(id,"pause",1,merchant,null,key()).status());assertEquals(404,history("public",id,30,null).status());}
 @Test void currentPublicationAndTenantPermissionBoundariesRemainEnforced(){String id=create();assertEquals(404,history("public",id,30,null).status());assertEquals(200,history("merchant",id,30,merchant).status());assertEquals(404,history("merchant",id,30,foreign).status());UUID savedStore=store;store=otherStore;String limited=identity("MERCHANT",merchantId,List.of("offer.read"));store=savedStore;assertEquals(404,history("merchant",id,30,limited).status());assertEquals(200,history("admin",id,30,reader).status());String noPermission=identity("ADMIN",null,List.of());assertEquals(403,history("admin",id,30,noPermission).status());assertEquals(200,state(id,"activate",0,merchant,null,key()).status());String consumer=identity("CONSUMER",null,List.of());assertEquals(200,history("consumer",id,30,consumer).status());assertEquals(403,history("merchant",id,30,consumer).status());db.update("UPDATE merchant SET status='SUSPENDED' WHERE id=?",merchantId);assertEquals(404,history("public",id,30,null).status());}
 @Test void invalidRangesMissingIdentityAndUnknownIdentifiersAreRejected(){String id=active();assertEquals(400,history("public",id,7,null).status());assertEquals(404,history("public",UUID.randomUUID().toString(),30,null).status());assertEquals(401,history("merchant",id,30,null).status());assertEquals(404,history("public","not-a-uuid",30,null).status());}
 @Test void laterPublicationDoesNotRevealEarlierUnpublishedPriceChanges(){String id=active();db.update("UPDATE sku_standard_versions SET status='RETIRED' WHERE sku_id=?",UUID.fromString(sku));assertEquals(404,history("public",id,30,null).status());assertEquals(200,patch(id,Map.of("sale_price_fen",1300),1).status());assertEquals(false,db.queryForObject("SELECT publicly_recorded FROM offer_price_snapshots WHERE offer_id=? ORDER BY id DESC LIMIT 1",Boolean.class,UUID.fromString(id)));db.update("INSERT INTO sku_standard_versions(id,sku_id,version_no,status,ingredients,nutrients,allergens_known,life_stage_ids,source_refs,source_updated_on,created_by,published_at) SELECT gen_random_uuid(),sku_id,2,'PUBLISHED',ingredients,nutrients,allergens_known,life_stage_ids,source_refs,source_updated_on,created_by,clock_timestamp() FROM sku_standard_versions WHERE sku_id=? AND version_no=1",UUID.fromString(sku));var h=history("public",id,30,null).data();assertEquals(1300,h.get("current_sale_price_fen").asInt());assertTrue(h.get("points").get(29).get("sale_price_fen").isNull());assertEquals(1300,history("merchant",id,30,merchant).data().get("points").get(29).get("sale_price_fen").asInt());}
}
